window.__OPENSTAX_PHYSICS__[3] = {"schemaVersion":"4.0.0-physics","generatedAt":"2026-11-27T01:44:27.212Z","number":3,"code":"ch03","slug":"acceleration","title":"Acceleration","titleVi":"Gia Tốc & Chuyển Động Biến Đổi Đều (Acceleration)","sections":[{"uid":"hsphys.ch03.sec00","moduleId":"m54119","number":"3.0","slug":"introduction","title":"Introduction","isIntroduction":true,"learningObjectives":[],"bilingualGuide":null,"keyEquations":[],"subsections":[{"uid":"hsphys.ch03.sec00.sub01","title":"Chapter Introduction","summaryVi":"Tổng quan mở đầu chương: Gia Tốc & Chuyển Động Biến Đổi Đều (Acceleration) — giới thiệu hiện tượng thực tế và các câu hỏi nền tảng trước khi đi vào định luật chi tiết.","paragraphs":["You may have heard the term accelerator , referring to the gas pedal in a car. When the gas pedal is pushed down, the flow of gasoline to the engine increases, which increases the car’s velocity . Pushing on the gas pedal results in acceleration because the velocity of the car increases, and acceleration is defined as a change in velocity. You need two quantities to define velocity: a speed and a direction. Changing either of these quantities, or both together, changes the velocity. You may be surprised to learn that pushing on the brake pedal or turning the steering wheel also causes acceleration. The first reduces the speed and so changes the velocity, and the second changes the direction and also changes the velocity.","In fact, any change in velocity—whether positive, negative, directional, or any combination of these—is called an acceleration in physics. The plane in the picture is said to be accelerating because its velocity is decreasing as it prepares to land. To begin our study of acceleration, we need to have a clear understanding of what acceleration means."],"figures":[{"sourceId":"fs-idm48780080","filename":"CNX_HSPhysics_03_00_plane.jpg","relativePath":"media/CNX_HSPhysics_03_00_plane.jpg","alt":"An airplane is flying over a beach area in St. Maarten as it comes in for a landing at the airport. The airplane's acceleration is in the opposite direction of its velocity."}],"tables":[]}],"workedExamples":[],"snapLabs":[],"tipsAndFeatures":[],"summaryPoints":[],"glossary":[],"assessments":[],"stats":{"learningObjectiveCount":0,"keyEquationCount":0,"subsectionCount":1,"workedExampleCount":0,"snapLabCount":0,"glossaryCount":0,"assessmentCount":0}},{"uid":"hsphys.ch03.sec01","moduleId":"m54123","number":"3.1","slug":"acceleration","title":"Acceleration","isIntroduction":false,"learningObjectives":["Explain acceleration and determine the direction and magnitude of acceleration in one dimension","Analyze motion in one dimension using kinematic equations and graphic representations"],"bilingualGuide":{"notebookSummaryVi":"Định nghĩa Gia tốc (a = Δv / Δt — đại lượng vectơ, đơn vị m/s²). Phân biệt chuyển động nhanh dần (a cùng dấu v) với chậm dần (a ngược dấu v).","wordProblemCues":[{"phraseEn":"starts from rest","meaningVi":"Bắt đầu từ trạng thái đứng yên → v₀ = 0","mathNotation":"v₀ = 0"},{"phraseEn":"comes to a stop / rest","meaningVi":"Dừng lại → v_f = 0","mathNotation":"v_f = 0"}],"commonTrapsVi":["⚠️ Bẫy dấu kinh điển: Gia tốc âm (a < 0) chỉ làm vật CHẬM DẦN khi v > 0. Nếu v < 0 và a < 0 thì vật đang tăng tốc theo chiều âm!"]},"keyEquations":[{"name":"Average acceleration","formula":"\\(\\bar{a} = \\frac{\\Delta v}{\\Delta t} = \\frac{{v}_{\\text{f}} - {v}_{0}}{{t}_{\\text{f}} - {t}_{o}}\\)"}],"subsections":[{"uid":"hsphys.ch03.sec01.sub01","title":"Defining Acceleration","summaryVi":"Định nghĩa Gia tốc (a = Δv / Δt — đại lượng vectơ, đơn vị m/s²). Phân biệt chuyển động nhanh dần (a cùng dấu v) với chậm dần (a ngược dấu v). Thuật ngữ trọng tâm trong mục này: average acceleration (Gia tốc trung bình), instantaneous acceleration (Gia tốc tức thời), negative acceleration (Gia tốc âm (ngược chiều dương)).","paragraphs":["Throughout this chapter we will use the following terms: time , displacement , velocity , and acceleration . Recall that each of these terms has a designated variable and SI unit of measurement as follows:","Acceleration is the change in velocity divided by a period of time during which the change occurs. The SI units of velocity are m/s and the SI units for time are s, so the SI units for acceleration are m/s 2 . Average acceleration is given by","Average acceleration is distinguished from instantaneous acceleration , which is acceleration at a specific instant in time. The magnitude of acceleration is often not constant over time. For example, runners in a race accelerate at a greater rate in the first second of a race than during the following seconds. You do not need to know all the instantaneous accelerations at all times to calculate average acceleration. All you need to know is the change in velocity (i.e., the final velocity minus the initial velocity) and the change in time (i.e., the final time minus the initial time), as shown in the formula. A component of the average acceleration can be positive, negative, or zero. A negative acceleration component is simply an acceleration in the negative direction along that axis. When the motion is in one dimension, we often simply refer to this as negative acceleration, and acceleration in the positive direction as positive acceleration.","Keep in mind that although acceleration points in the same direction as the change in velocity, it is not always in the direction of the velocity itself. When an object slows down, its acceleration is opposite to the direction of its velocity. In everyday language, this is called deceleration; but in physics, it is acceleration—whose direction happens to be opposite that of the velocity. For now, let us assume that motion to the right along the x -axis is positive and motion to the left is negative .","Figure 3.1 shows a car with positive acceleration in (a) and negative acceleration in (b). The arrows represent vectors showing both direction and magnitude of velocity and acceleration.","Velocity and acceleration are both vector quantities . Recall that vectors have both magnitude and direction. An object traveling at a constant speed does accelerate if it changes direction. So, turning the steering wheel of a moving car makes the car accelerate because the velocity changes direction.","With this animation , you can produce both variations of acceleration and velocity shown in Figure 3.1, plus a few more variations. Vary the velocity and acceleration by sliding the red and green markers along the scales. Keeping the velocity marker near zero will make the effect of acceleration more obvious. Try changing acceleration from positive to negative while the man is moving. We will come back to this animation and look at the Charts view when we study graphical representation of motion.","Which part, (a) or (b), is represented when the velocity vector is on the positive side of the scale and the acceleration vector is set on the negative side of the scale? What does the cars motion look like for the given scenario?"],"figures":[{"sourceId":"fs-idp52490976","filename":"CNX_HSPhysics_03_01_car.jpg","relativePath":"media/CNX_HSPhysics_03_01_car.jpg","alt":"Two similar cars are shown. The first car is speeding up as indicated by a velocity vector and an acceleration vector pointing to the right. The second car is slowing down as indicated by a velocity vector pointing to the right and an acceleration vector pointing to the left. Unlabeled x and y-axes are shown for reference."},{"sourceId":"fs-id1169827344794","filename":"CNX_HSPhysics_03_01_car.jpg","relativePath":"media/CNX_HSPhysics_03_01_car.jpg","alt":"Two similar cars are shown. The first car is speeding up as indicated by a velocity vector and an acceleration vector pointing to the right. The second car is slowing down as indicated by a velocity vector pointing to the right and an acceleration vector pointing to the left. Unlabeled x and y-axes are shown for reference."}],"tables":[]},{"uid":"hsphys.ch03.sec01.sub02","title":"Calculating Average Acceleration","summaryVi":"Định nghĩa Gia tốc (a = Δv / Δt — đại lượng vectơ, đơn vị m/s²). Phân biệt chuyển động nhanh dần (a cùng dấu v) với chậm dần (a ngược dấu v). Thuật ngữ trọng tâm trong mục này: average acceleration (Gia tốc trung bình).","paragraphs":["Look back at the equation for average acceleration. You can see that the calculation of average acceleration involves three values: change in time, (Δ t ); change in velocity, (Δ v ); and acceleration ( a ).","Change in time is often stated as a time interval, and change in velocity can often be calculated by subtracting the initial velocity from the final velocity. Average acceleration is then simply change in velocity divided by change in time. Before you begin calculating, be sure that all distances and times have been converted to meters and seconds. Look at these examples of acceleration of a subway train.","Recall that for analysis of motion in only one dimension, we do not need to use vectors. Instead, we can treat displacement, velocity, and acceleration as scalars. Unlike magnitudes, scalars can be positive or negative, so the sign can serve to tell us the direction along the one-dimensional axis."],"figures":[],"tables":[]}],"workedExamples":[{"uid":"hsphys.ch03.sec01.ex01","number":"3.1.1","title":"An Accelerating Subway Train","problem":"A subway train accelerates from rest to 30.0 km/h in 20.0 s. What is the average acceleration during that time interval?","problemImages":[],"strategy":"Start by making a simple sketch.\nThis problem involves four steps:\nConvert to units of meters and seconds.\nDetermine the change in velocity.\nDetermine the change in time.\nUse these values to calculate the average acceleration.","solution":"Identify the knowns. Be sure to read the problem for given information, which may not look like numbers. When the problem states that the train starts from rest, you can write down that the initial velocity is 0 m/s. Therefore, v 0 = 0; v f = 30.0 km/h; and Δ t = 20.0 s.\nConvert the units.\n\\(\\frac{\\text{30}\\text{.0 km}}{\\text{h}}\\text{×}\\frac{{\\text{10}}^{\\text{3}}\\text{m}}{\\text{1 km}}\\text{×}\\frac{\\text{1 h}}{\\text{3600 s}}\\text{= 8}\\text{.333}\\frac{\\text{m}}{\\text{s}}\\)\nCalculate change in velocity, \\(\\Delta v = {v}_{\\text{f}}\\text{–}{v}_{\\text{0}}\\text{= 8}\\text{.333 m/s – 0 = + 8}\\text{.333 m/s,}\\)\nwhere the plus sign means the change in velocity is to the right.\nWe know Δ t , so all we have to do is insert the known values into the formula for average acceleration.\n\\(\\bar{a} = \\frac{\\Delta v}{\\Delta t} = \\frac{8.333\\,\\text{m/s}}{20.00\\,\\text{s}} = + 0.417\\frac{\\text{m}}{{\\text{s}}^{\\text{2}}}\\)","solutionImages":[],"solutionTables":[],"discussion":"The plus sign in the answer means that acceleration is to the right. This is a reasonable conclusion because the train starts from rest and ends up with a velocity directed to the right (i.e., positive). So, acceleration is in the same direction as the change in velocity, as it should be."},{"uid":"hsphys.ch03.sec01.ex02","number":"3.1.2","title":"An Accelerating Subway Train","problem":"Now, suppose that at the end of its trip, the train slows to a stop in 8.00 s from a speed of 30.0 km/h. What is its average acceleration during this time?","problemImages":[],"strategy":"Again, make a simple sketch.\nIn this case, the train is decelerating and its acceleration is negative because it is pointing to the left. As in the previous example, we must find the change in velocity and change in time, then solve for acceleration.","solution":"Identify the knowns: v 0 = 30.0 km/h; v f = 0; and Δ t = 8.00 s.\nConvert the units. From the first problem, we know that 30.0 km/h = 8.333 m/s.\nCalculate change in velocity, \\(\\Delta v = {v}_{\\text{f}} - {v}_{0} = 0 - 8.333\\,\\text{m/s} = - 8.333\\,\\text{m/s,}\\) where the minus sign means that the change in velocity points to the left.\nWe know Δ t = 8.00 s, so all we have to do is insert the known values into the equation for average acceleration.\n\\(\\bar{a} = \\frac{\\Delta v}{\\Delta t} = \\frac{- 8.333\\,\\text{m/s}}{8.00\\,\\text{s}} = - 1.04\\frac{\\text{m}}{{\\text{s}}^{\\text{2}}}\\)","solutionImages":[],"solutionTables":[],"discussion":"The minus sign indicates that acceleration is to the left. This is reasonable because the train initially has a positive velocity in this problem, and a negative acceleration would reduce the velocity. Again, acceleration is in the same direction as the change in velocity, which is negative in this case. This acceleration can be called a deceleration because it has a direction opposite to the velocity.\nIt is easier to get plus and minus signs correct if you always assume that motion is away from zero and toward positive values on the x -axis. This way v always starts off being positive and points to the right. If speed is increasing, then acceleration is positive and also points to the right. If speed is decreasing, then acceleration is negative and points to the left.\nIt is a good idea to carry two extra significant figures from step-to-step when making calculations. Do not round off with each step. When you arrive at the final answer, apply the rules of significant figures for the operations you carried out and round to the correct number of digits. Sometimes this will make your answer slightly more accurate."}],"snapLabs":[{"uid":"hsphys.ch03.sec01.lab01","title":"Measure the Acceleration of a Bicycle on a Slope","text":"In this lab you will take measurements to determine if the acceleration of a moving bicycle is constant. If the acceleration is constant, then the following relationships hold: \\(\\bar{v} = \\frac{\\Delta d}{\\Delta t} = \\frac{{v}_{0} + {v}_{\\text{f}}}{2}\\) If \\({v}_{0} = 0\\), then \\({v}_{\\text{f}} = 2\\bar{v}\\)\nand \\(\\bar{a} = \\frac{{v}_{\\text{f}}}{\\Delta t}\\)\nYou will work in pairs to measure and record data for a bicycle coasting down an incline on a smooth, gentle slope. The data will consist of distances traveled and elapsed times.\nFind an open area to minimize the risk of injury during this lab.\nstopwatch\nmeasuring tape\nbicycle\nFind a gentle, paved slope, such as an incline on a bike path. The more gentle the slope, the more accurate your data will likely be.\nMark uniform distances along the slope, such as 5 m, 10 m, etc.\nDetermine the following roles: the bike rider, the timer, and the recorder. The recorder should create a data table to collect the distance and time data.\nHave the rider at the starting point at rest on the bike. When the timer calls Start , the timer starts the stopwatch and the rider begins coasting down the slope on the bike without pedaling.\nHave the timer call out the elapsed times as the bike passes each marked point. The recorder should record the times in the data table. It may be necessary to repeat the process to practice roles and make necessary adjustments.\nOnce acceptable data has been recorded, switch roles. Repeat Steps 3–5 to collect a second set of data.\nSwitch roles again to collect a third set of data.\nCalculate average acceleration for each set of distance-time data. If your result for \\(\\bar{a}\\) is not the same for different pairs of Δ v and Δ t , then acceleration is not constant.\nInterpret your results.","images":[]}],"tipsAndFeatures":[{"uid":"hsphys.ch03.sec01.feat01","type":"tip","title":"Tips for Success","text":"It is easier to get plus and minus signs correct if you always assume that motion is away from zero and toward positive values on the x -axis. This way v always starts off being positive and points to the right. If speed is increasing, then acceleration is positive and also points to the right. If speed is decreasing, then acceleration is negative and points to the left.\nIt is a good idea to carry two extra significant figures from step-to-step when making calculations. Do not round off with each step. When you arrive at the final answer, apply the rules of significant figures for the operations you carried out and round to the correct number of digits. Sometimes this will make your answer slightly more accurate.","images":[]}],"summaryPoints":["Acceleration is the rate of change of velocity. Its magnitude is expressed in units of m/s 2 .","The components of acceleration may be positive or negative."],"glossary":[{"term":"average acceleration","termVi":"Gia tốc trung bình","ipa":"/ˈæv.ər.ɪdʒ əkˌsel.əˈreɪ.ʃən/","definition":"change in velocity divided by the time interval over which it changed","definitionVi":"Độ biến thiên vận tốc chia cho khoảng thời gian: a_avg = Δv / Δt (đơn vị m/s²).","memoryTipVi":"Cho biết trung bình mỗi giây vận tốc thay đổi bao nhiêu m/s."},{"term":"instantaneous acceleration","termVi":"Gia tốc tức thời","ipa":"/ˌɪn.stənˈteɪ.ni.əs/","definition":"rate of change of velocity at a specific instant in time","definitionVi":"Gia tốc của vật tại một thời điểm xác định (độ dốc tiếp tuyến đồ thị v–t).","memoryTipVi":"Trong chuyển động thẳng biến đổi đều, gia tốc tức thời bằng gia tốc trung bình."},{"term":"negative acceleration","termVi":"Gia tốc âm (ngược chiều dương)","ipa":"/ˈneɡ.ə.tɪv/","definition":"a component of acceleration in the negative direction of the component axis","definitionVi":"Gia tốc hướng theo chiều âm của trục tọa độ quy ước.","memoryTipVi":"⚠️ False Friend: Gia tốc âm KHÔNG luôn có nghĩa là chậm dần! Nếu v < 0 và a < 0 (cùng dấu) thì vật đang NHANH DẦN theo chiều âm!"}],"assessments":[{"uid":"hsphys.ch03.sec01.q001","sourceId":"fs-idm96016","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"What are three ways an object can accelerate?","images":[],"choices":[{"label":"a","text":"By speeding up, maintaining constant velocity, or changing direction"},{"label":"b","text":"By speeding up, slowing down, or changing direction"},{"label":"c","text":"By maintaining constant velocity, slowing down, or changing direction"},{"label":"d","text":"By speeding up, slowing down, or maintaining constant velocity"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch03.sec01.q002","sourceId":"fs-idm7907216","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"What is the difference between average acceleration and instantaneous acceleration?","images":[],"choices":[{"label":"a","text":"Average acceleration is the change in displacement divided by the elapsed time; instantaneous acceleration is the acceleration at a given point in time."},{"label":"b","text":"Average acceleration is acceleration at a given point in time; instantaneous acceleration is the change in displacement divided by the elapsed time."},{"label":"c","text":"Average acceleration is the change in velocity divided by the elapsed time; instantaneous acceleration is acceleration at a given point in time."},{"label":"d","text":"Average acceleration is acceleration at a given point in time; instantaneous acceleration is the change in velocity divided by the elapsed time."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch03.sec01.q006","sourceId":"fs-idm94893408","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"How can you use the definition of acceleration to explain the units in which acceleration is measured?","images":[],"choices":[{"label":"a","text":"Acceleration is the rate of change of velocity. Therefore, its unit is m/s 2 ."},{"label":"b","text":"Acceleration is the rate of change of displacement. Therefore, its unit is m/s."},{"label":"c","text":"Acceleration is the rate of change of velocity. Therefore, its unit is m 2 /s."},{"label":"d","text":"Acceleration is the rate of change of displacement. Therefore, its unit is m 2 /s."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch03.sec01.q013","sourceId":"fs-idp25246160","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"The driver of a sports car traveling at 10.0 m/s steps down hard on the accelerator for 5.0 s and the velocity increases to 30.0 m/s. What was the average acceleration of the car during the 5.0 s time interval?","images":[],"choices":[{"label":"a","text":"–1.0 × 10 2 m/s 2"},{"label":"b","text":"–4.0 m/s 2"},{"label":"c","text":"4.0 m/s 2"},{"label":"d","text":"1.0 × 10 2 m/s 2"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch03.sec01.q014","sourceId":"fs-idp59012320","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"A girl rolls a basketball across a basketball court. The ball slowly decelerates at a rate of -0.20 m/s 2 . If the initial velocity was 2.0 m/s and the ball rolled to a stop at 5.0 sec after 12:00 p.m., at what time did she start the ball rolling?","images":[],"choices":[{"label":"a","text":"0.1 seconds before noon"},{"label":"b","text":"0.1 seconds after noon"},{"label":"c","text":"5 seconds before noon"},{"label":"d","text":"5 seconds after noon"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch03.sec01.q015","sourceId":"fs-idm9033648","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"Which variable represents displacement?","images":[],"choices":[{"label":"a","text":"a"},{"label":"b","text":"d"},{"label":"c","text":"t"},{"label":"d","text":"v"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch03.sec01.q016","sourceId":"fs-idm141844320","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"If a velocity increases from 0 to 20 m/s in 10 s, what is the average acceleration?","images":[],"choices":[{"label":"a","text":"0.5 m/s 2"},{"label":"b","text":"2 m/s 2"},{"label":"c","text":"10 m/s 2"},{"label":"d","text":"30 m/s 2"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch03.sec01.q017","sourceId":"fs-idm40699088","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"True or FalseThe vector for a negative acceleration points in the opposite direction when compared to the vector for a positive acceleration.","images":[],"choices":[{"label":"a","text":"True"},{"label":"b","text":"False"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch03.sec01.q019","sourceId":"fs-idp30486784","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"How is the vector arrow representing an acceleration of magnitude 3 m/s 2 different from the vector arrow representing a negative acceleration of magnitude 3 m/s 2 ?","images":[],"choices":[{"label":"a","text":"They point in the same direction."},{"label":"b","text":"They are perpendicular, forming a 90° angle between each other."},{"label":"c","text":"They point in opposite directions."},{"label":"d","text":"They are perpendicular, forming a 270° angle between each other."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch03.sec01.q020","sourceId":"fs-idm39098688","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"How long does it take to accelerate from 8.0 m/s to 20.0 m/s at a rate of acceleration of 3.0 m/s 2 ?","images":[],"choices":[{"label":"a","text":"0.25 s"},{"label":"b","text":"4.0 s"},{"label":"c","text":"9.33 s"},{"label":"d","text":"36 s"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch03.sec01.q022","sourceId":"fs-idm75037648","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"A car accelerates from rest at a stop sign at a rate of 3.0 m/s 2 to a speed of 21.0 m/s, and then immediately begins to decelerate to a stop at the next stop sign at a rate of 4.0 m/s 2 . How long did it take the car to travel from the first stop sign to the second stop sign? Show your work.","images":[],"choices":[{"label":"a","text":"1.7 seconds"},{"label":"b","text":"5.3 seconds"},{"label":"c","text":"7.0 seconds"},{"label":"d","text":"12 seconds"}],"hasOfficialSolution":false,"solution":null}],"stats":{"learningObjectiveCount":2,"keyEquationCount":1,"subsectionCount":2,"workedExampleCount":2,"snapLabCount":1,"glossaryCount":3,"assessmentCount":11}},{"uid":"hsphys.ch03.sec02","moduleId":"m54116","number":"3.2","slug":"representing-acceleration-with-equations-and-graphs","title":"Representing Acceleration with Equations and Graphs","isIntroduction":false,"learningObjectives":["Explain the kinematic equations related to acceleration and illustrate them with graphs","Apply the kinematic equations and related graphs to problems involving acceleration"],"bilingualGuide":{"notebookSummaryVi":"Bộ 4 phương trình Động học (Kinematic Equations) cho chuyển động thẳng biến đổi đều và bài toán Rơi tự do (Free Fall, g = 9.80 m/s²).","wordProblemCues":[{"phraseEn":"free fall / dropped from rest","meaningVi":"Rơi tự do không vận tốc đầu (v₀ = 0, a = -g)","mathNotation":"g = 9.8 m/s²"}],"commonTrapsVi":["Khi chọn chiều dương hướng LÊN, gia tốc trọng trường luôn mang dấu âm: a = -9.80 m/s² (kể cả lúc vật đang bay lên lẫn lúc rơi xuống!)."]},"keyEquations":[{"name":"Average velocity","formula":"\\(d = {d}_{0} + \\bar{v}t\\), or \\(\\bar{v} = \\frac{d}{t}\\) when d 0 = 0"},{"name":"Average velocity","formula":"\\(\\bar{v} = \\frac{{v}_{0} + {v}_{\\text{f}}}{2}\\)"},{"name":"Velocity with constant acceleration","formula":"\\(v = {v}_{0} + at\\), or \\(v = at\\) when v 0 = 0"},{"name":"Displacement with constant acceleration","formula":"\\(d = {d}_{0} + {v}_{0}t + \\frac{1}{2}a{t}^{2}\\), or \\(a = \\frac{2d}{{t}^{2}}\\) when d 0 = 0 and v 0 = 0"},{"name":"Constant acceleration","formula":"\\({v}^{2} = {v}_{0}^{2} + 2a(d - {d}_{0})\\), or \\(a = \\frac{{v}^{2}}{2d}\\) when d 0 = 0 and v 0 = 0"}],"subsections":[{"uid":"hsphys.ch03.sec02.sub01","title":"How the Kinematic Equations are Related to Acceleration","summaryVi":"Bộ 4 phương trình Động học (Kinematic Equations) cho chuyển động thẳng biến đổi đều và bài toán Rơi tự do (Free Fall, g = 9.80 m/s²). Thuật ngữ trọng tâm trong mục này: constant acceleration (Gia tốc không đổi (Biến đổi đều)), kinematic equations (Các phương trình động học).","paragraphs":["We are studying concepts related to motion: time, displacement, velocity , and especially acceleration. We are only concerned with motion in one dimension. The kinematic equations that we will be using apply to conditions of constant acceleration, except where noted, and show how these concepts are related. Constant acceleration is acceleration that does not change over time. The first kinematic equation relates displacement d , average velocity \\(\\bar{v}\\), and time t .","\\(d = {d}_{0} + \\bar{v}t\\)\nThe initial displacement \\({d}_{0}\\)\nis often 0, in which case the equation can be written as \\(\\bar{v} = \\frac{d}{t}\\)","This equation, which is the definition of average velocity and valid for both constant and non-constant acceleration, says that average velocity is displacement per unit time. We will express velocity in meters per second. If we graph displacement versus time, as in Figure 3.2, the slope will be the velocity. Whenever a rate, such as velocity, is represented graphically, time is usually taken to be the independent variable and is plotted along the x axis.","The second kinematic equation, another expression for average velocity \\(\\bar{v},\\)\nis simply the initial velocity plus the final velocity divided by two. This equation is only valid for constant acceleration.","Now we come to our main focus of this chapter; namely, the kinematic equations that describe motion with constant acceleration. In the third kinematic equation, acceleration is the rate at which velocity increases, so velocity at any point equals initial velocity plus acceleration multiplied by time","Note that this third kinematic equation does not have displacement in it. Therefore, if you do not know the displacement and are not trying to solve for a displacement, this equation might be a good one to use.","The third kinematic equation is also represented by the graph in Figure 3.2.","The fourth kinematic equation shows how displacement is related to acceleration","When starting at the origin, \\({d}_{0} = 0\\) and, when starting from rest, \\({v}_{0} = 0\\), in which case the equation can be written as","This equation tells us that, for constant acceleration, the slope of a plot of 2 d versus t 2 is acceleration, as shown in Figure 3.2.","The fifth kinematic equation relates velocity, acceleration, and displacement","This equation is useful for when we do not know, or do not need to know, the time.","When starting from rest, the fifth equation simplifies to","According to this equation, a graph of velocity squared versus twice the displacement will have a slope equal to acceleration.","Note that, in reality, knowns and unknowns will vary. Sometimes you will want to rearrange a kinematic equation so that the knowns are the values on the axes and the unknown is the slope. Sometimes the intercept will not be at the origin (0,0). This will happen when v 0 or d 0 is not zero. This will be the case when the object of interest is already in motion, or the motion begins at some point other than at the origin of the coordinate system.","Look at the Moving Man simulation again and this time use the Charts view. Again, vary the velocity and acceleration by sliding the red and green markers along the scales. Keeping the velocity marker near zero will make the effect of acceleration more obvious. Observe how the graphs of position, velocity, and acceleration vary with time. Note which are linear plots and which are not.","On a velocity versus time plot, what does the slope represent?","On a position versus time plot, what does the slope represent?","The kinematic equations are applicable when you have constant acceleration."],"figures":[{"sourceId":"fs-idp23485472","filename":"CNX_HSPhysics_03_02_displace.jpg","relativePath":"media/CNX_HSPhysics_03_02_displace.jpg","alt":"A line graph is shown. The x-axis is labeled time and includes a directional arrow pointing to the right. The y-axis is labeled displacement and includes a directional arrow pointing upward. The graphed line shows a directly proportional relationship between time and displacement."},{"sourceId":"fs-idp32841888","filename":"CNX_HSPhysics_03_02_time.jpg","relativePath":"media/CNX_HSPhysics_03_02_time.jpg","alt":"A line graph is shown. The x-axis is labeled time in seconds and the y-axis is labeled velocity in meters per second. The graphed line shows a directly proportional relationship between time and velocity."},{"sourceId":"fs-idm11377424","filename":"CNX_HSPhysics_03_02_line.jpg","relativePath":"media/CNX_HSPhysics_03_02_line.jpg","alt":"A line graph is shown. The x-axis is labeled t squared and the y-axis is labeled two d in meters. The graphed line shows that the slope of two d versus t squared equals constant acceleration."},{"sourceId":"fs-idm61803632","filename":"CNX_HSPhysics_03_02_slope.jpg","relativePath":"media/CNX_HSPhysics_03_02_slope.jpg","alt":"A line graph is shown. The x-axis is labeled two d in meters and the y-axis is labeled v squared in meters per second squared. The graphed line shows a directly proportional relationship between two d, twice the displacement, and v squared, velocity squared."}],"tables":[]},{"uid":"hsphys.ch03.sec02.sub02","title":"Applying Kinematic Equations to Situations of Constant Acceleration","summaryVi":"Bộ 4 phương trình Động học (Kinematic Equations) cho chuyển động thẳng biến đổi đều và bài toán Rơi tự do (Free Fall, g = 9.80 m/s²).","paragraphs":["Problem-solving skills are essential to success in a science and life in general. The ability to apply broad physical principles, which are often represented by equations, to specific situations is a very powerful form of knowledge. It is much more powerful than memorizing a list of facts. Analytical skills and problem-solving abilities can be applied to new situations, whereas a list of facts cannot be made long enough to contain every possible circumstance. Essential analytical skills will be developed by solving problems in this text and will be useful for understanding physics and science in general throughout your life.","While no single step-by-step method works for every problem, the following general procedures facilitate problem solving and make the answers more meaningful. A certain amount of creativity and insight are required as well."],"figures":[],"tables":[]},{"uid":"hsphys.ch03.sec02.sub03","title":"Constant Acceleration","summaryVi":"Bộ 4 phương trình Động học (Kinematic Equations) cho chuyển động thẳng biến đổi đều và bài toán Rơi tự do (Free Fall, g = 9.80 m/s²). Thuật ngữ trọng tâm trong mục này: acceleration due to gravity (Gia tốc rơi tự do / Gia tốc trọng trường (g)), constant acceleration (Gia tốc không đổi (Biến đổi đều)).","paragraphs":["In many cases, acceleration is not uniform because the force acting on the accelerating object is not constant over time. A situation that gives constant acceleration is the acceleration of falling objects. When air resistance is not a factor, all objects near Earth’s surface fall with an acceleration of about 9.80 m/s 2 . Although this value decreases slightly with increasing altitude, it may be assumed to be essentially constant. The value of 9.80 m/s 2 is labeled g and is referred to as acceleration due to gravity . Gravity is the force that causes nonsupported objects to accelerate downward—or, more precisely, toward the center of Earth. The magnitude of this force is called the weight of the object and is given by mg where m is the mass of the object (in kg). In places other than on Earth, such as the Moon or on other planets, g is not 9.80 m/s 2 , but takes on other values. When using g for the acceleration a in a kinematic equation, it is usually given a negative sign because the acceleration due to gravity is downward."],"figures":[],"tables":[]},{"uid":"hsphys.ch03.sec02.sub04","title":"Performance Task","summaryVi":"Bộ 4 phương trình Động học (Kinematic Equations) cho chuyển động thẳng biến đổi đều và bài toán Rơi tự do (Free Fall, g = 9.80 m/s²). Thuật ngữ trọng tâm trong mục này: kinematic equations (Các phương trình động học).","paragraphs":["Design an experiment to measure displacement and elapsed time. Use the data to calculate final velocity, average velocity, acceleration, and acceleration.","(a) How would you use the garden hose, stopwatch, marble, measuring tape, and slope to measure displacement and elapsed time? Hint—The marble is the accelerating object, and the length of the hose is total displacement.","(b) How would you use the displacement and time data to calculate velocity, average velocity, and acceleration? Which kinematic equations would you use?","(c) How would you use the materials, the measured and calculated data, and the flat area below the slope to determine the negative acceleration? What would you measure, and which kinematic equation would you use?"],"figures":[],"tables":[]}],"workedExamples":[{"uid":"hsphys.ch03.sec02.ex01","number":"3.2.1","title":"Acceleration of a Dragster","problem":"The time it takes for a dragster to cross the finish line is unknown. The dragster accelerates from rest at 26 m/s 2 for a quarter mile (0.250 mi). What is the final velocity of the dragster?","problemImages":[],"strategy":"The equation \\({v}^{2} = {v}_{0}^{2} + 2a(d - {d}_{0})\\) is ideally suited to this task because it gives the velocity from acceleration and displacement, without involving the time.","solution":"Convert miles to meters.\n\\((0.250\\,\\text{mi}) \\times \\frac{1609\\,\\text{m}}{1\\,\\text{mi}} = 402\\,\\text{m}\\)\nIdentify the known values. We know that v 0 = 0 since the dragster starts from rest, and we know that the distance traveled, d - d 0 is 402 m. Finally, the acceleration is constant at a = 26.0 m/s 2 .\nInsert the knowns into the equation \\({v}^{2} = {v}_{0}^{2} + 2a(d - {d}_{0})\\) and solve for v .\n\\({v}^{2} = 0 + 2(26.0\\frac{\\text{m}}{{\\text{s}}^{\\text{2}}})(402\\,\\text{m}) = 2.09 \\times {10}^{4}\\frac{{\\text{m}}^{\\text{2}}}{{\\text{s}}^{\\text{2}}}\\)\nTaking the square root gives us \\(v = \\sqrt{2.09 \\times {10}^{4}\\frac{{\\text{m}}^{\\text{2}}}{{\\text{s}}^{\\text{2}}}} = 145\\frac{\\text{m}}{\\text{s}}\\text{.}\\)","solutionImages":[],"solutionTables":[],"discussion":"145 m/s is about 522 km/hour or about 324 mi/h, but even this breakneck speed is short of the record for the quarter mile. Also, note that a square root has two values. We took the positive value because we know that the velocity must be in the same direction as the acceleration for the answer to make physical sense.\nAn examination of the equation \\({v}^{2} = {v}_{0}^{2} + 2a(d - {d}_{0})\\) can produce further insights into the general relationships among physical quantities:\nThe final velocity depends on the magnitude of the acceleration and the distance over which it applies.\nFor a given acceleration, a car that is going twice as fast does not stop in twice the distance—it goes much further before it stops. This is why, for example, we have reduced speed zones near schools."},{"uid":"hsphys.ch03.sec02.ex02","number":"3.2.2","title":"Falling Objects","problem":"A person standing on the edge of a high cliff throws a rock straight up with an initial velocity v 0 of 13 m/s.\n(a) Calculate the position and velocity of the rock at 1.00, 2.00, and 3.00 seconds after it is thrown. Ignore the effect of air resistance.","problemImages":[],"strategy":"Sketch the initial velocity and acceleration vectors and the axes.\nInitial conditions for rock thrown straight up.\nList the knowns: time t = 1.00 s, 2.00 s, and 3.00 s; initial velocity v 0 = 13 m/s; acceleration a = g = –9.80 m/s 2 ; and position y 0 = 0 m\nList the unknowns: y 1 , y 2 , and y 3 ; v 1 , v 2 , and v 3 —where 1, 2, 3 refer to times 1.00 s, 2.00 s, and 3.00 s\nChoose the equations.\n\\(d = {d}_{0} + {v}_{0}t + \\frac{1}{2}a{t}^{2}\\,\\text{becomes}\\,y = {y}_{0} + {v}_{0}t - \\frac{1}{2}g{t}^{2}\\)\n\\(v = {v}_{0} + at\\,\\text{becomes}\\,v = {v}_{0} + - gt\\)\nThese equations describe the unknowns in terms of knowns only.","solution":"\\(\\begin{aligned} {y}_{1} = 0 + (13.0\\,\\text{m/s})(1.00\\,\\text{s}) + \\frac{( - 9.80{\\text{m/s}}^{2}){(1.00\\,\\text{s})}^{2}}{2} = 8.10\\,\\text{m} \\\\ {y}_{2} = 0 + (13.0\\,\\text{m/s})(2.00\\,\\text{s}) + \\frac{( - 9.80{\\text{m/s}}^{2}){(2.00\\,\\text{s})}^{2}}{2} = 6.40\\,\\text{m} \\\\ {y}_{3} = 0 + (13.0\\,\\text{m/s})(3.00\\,\\text{s}) + \\frac{( - 9.80{\\text{m/s}}^{2}){(3.00\\,\\text{s})}^{2}}{2} = - 5.10\\,\\text{m} \\\\ {v}_{1} = 13.0\\,\\text{m/s} + ( - 9.80{\\text{m/s}}^{2})(1.00\\,\\text{s}) = 3.20\\,\\text{m/s} \\\\ {v}_{2} = 13.0\\,\\text{m/s} + ( - 9.80{\\text{m/s}}^{2})(2.00\\,\\text{s}) = - 6.60\\,\\text{m/s} \\\\ {v}_{3} = 13.0\\,\\text{m/s} + ( - 9.80{\\text{m/s}}^{2})(3.00\\,\\text{s}) = - 16.4\\,\\text{m/s} \\end{aligned}\\)","solutionImages":[],"solutionTables":[],"discussion":"The first two positive values for y show that the rock is still above the edge of the cliff, and the third negative y value shows that it has passed the starting point and is below the cliff. Remember that we set up to be positive. Any position with a positive value is above the cliff, and any velocity with a positive value is an upward velocity. The first value for v is positive, so the rock is still on the way up. The second and third values for v are negative, so the rock is on its way down."}],"snapLabs":[],"tipsAndFeatures":[{"uid":"hsphys.ch03.sec02.feat01","type":"physics-in-action","title":"Effects of Rapid Acceleration","text":"Astronauts train using G Force Simulators. (NASA)\nWhen in a vehicle that accelerates rapidly, you experience a force on your entire body that accelerates your body. You feel this force in automobiles and slightly more on amusement park rides. For example, when you ride in a car that turns, the car applies a force on your body to make you accelerate in the direction in which the car is turning. If enough force is applied, you will accelerate at 9.80 m/s 2 . This is the same as the acceleration due to gravity, so this force is called one G.\nOne G is the force required to accelerate an object at the acceleration due to gravity at Earth’s surface. Thus, one G for a paper cup is much less than one G for an elephant, because the elephant is much more massive and requires a greater force to make it accelerate at 9.80 m/s 2 . For a person, a G of about 4 is so strong that his or her face will distort as the bones accelerate forward through the loose flesh. Other symptoms at extremely high Gs include changes in vision, loss of consciousness, and even death. The space shuttle produces about 3 Gs during takeoff and reentry. Some roller coasters and dragsters produce forces of around 4 Gs for their occupants. A fighter jet can produce up to 12 Gs during a sharp turn.\nAstronauts and fighter pilots must undergo G-force training in simulators. The video shows the experience of several people undergoing this training.\nPeople, such as astronauts, who work with G forces must also be trained to experience zero G—also called free fall or weightlessness—which can cause queasiness. NASA has an aircraft that allows it occupants to experience about 25 s of free fall. The aircraft is nicknamed the Vomit Comet .\nA common way to describe acceleration is to express it in multiples of g , Earth's gravitational acceleration. If a dragster accelerates at a rate of 39.2 m/s 2 , how many g 's does the driver experience?\n1.5 g\n4.0 g\n10.5 g\n24.5 g","images":[{"sourceId":"fs-idm29574496","filename":"CNX_HSPhysics_03_02_GForce.jpg","relativePath":"media/CNX_HSPhysics_03_02_GForce.jpg","alt":"An astronaut is strapped into a G-Force simulator."}]}],"summaryPoints":["The kinematic equations show how time, displacement, velocity, and acceleration are related for objects in motion.","In general, kinematic problems can be solved by identifying the kinematic equation that expresses the unknown in terms of the knowns.","Displacement, velocity, and acceleration may be displayed graphically versus time.","The kinematic equations in this section are valid only for constant acceleration."],"glossary":[{"term":"acceleration due to gravity","termVi":"Gia tốc rơi tự do / Gia tốc trọng trường (g)","ipa":"/ˈɡræv.ə.ti/","definition":"acceleration of an object that is subject only to the force of gravity; near Earth’s surface this acceleration is 9.80 m/s 2","definitionVi":"Gia tốc của vật rơi tự do gần mặt đất: g ≈ 9.80 m/s² (hướng thẳng đứng xuống dưới).","memoryTipVi":"Mọi vật rơi tự do trong chân không đều có cùng gia tốc g không phụ thuộc khối lượng."},{"term":"constant acceleration","termVi":"Gia tốc không đổi (Biến đổi đều)","ipa":"/ˈkɒn.stənt/","definition":"acceleration that does not change with respect to time","definitionVi":"Chuyển động có gia tốc không đổi về cả độ lớn lẫn hướng theo thời gian.","memoryTipVi":"Điều kiện bắt buộc để áp dụng 4 phương trình động học (Kinematic Equations)."},{"term":"kinematic equations","termVi":"Các phương trình động học","ipa":"/ˌkɪn.əˈmæt.ɪk/","definition":"the five equations that describe constant acceleration motion in terms of time, displacement, velocity, and acceleration","definitionVi":"Bộ 4 công thức liên hệ giữa d, v₀, v, a, t cho chuyển động thẳng biến đổi đều.","memoryTipVi":"v = v₀ + at; d = d₀ + v₀t + ½at²; v² = v₀² + 2a(d - d₀)."}],"assessments":[{"uid":"hsphys.ch03.sec02.q001","sourceId":"fs-idm78831712","category":"check-understanding","categoryLabel":"Check Your Understanding (Kiểm tra đọc hiểu)","isMultipleChoice":true,"prompt":"Identify the four variables found in the kinematic equations.","images":[],"choices":[{"label":"a","text":"Displacement, Force, Mass, and Time"},{"label":"b","text":"Acceleration, Displacement, Time, and Velocity"},{"label":"c","text":"Final Velocity, Force, Initial Velocity, and Mass"},{"label":"d","text":"Acceleration, Final Velocity, Force, and Initial Velocity"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch03.sec02.q004","sourceId":"fs-id1167066955525","category":"practice-problems","categoryLabel":"Practice Problems (Bài tập vận dụng)","isMultipleChoice":true,"prompt":"Dragsters can reach a top speed of 145 m/s in only 4.45 s. Calculate the average acceleration for such a dragster.","images":[],"choices":[{"label":"a","text":"-32.6 m/s 2"},{"label":"b","text":"0 m/s 2"},{"label":"c","text":"32.6 m/s 2"},{"label":"d","text":"145 m/s 2"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch03.sec02.q005","sourceId":"fs-id1167067087927","category":"practice-problems","categoryLabel":"Practice Problems (Bài tập vận dụng)","isMultipleChoice":true,"prompt":"An Olympic-class sprinter starts a race with an acceleration of 4.50 m/s 2 . Assuming she can maintain that acceleration, what is her speed 2.40 s later?","images":[],"choices":[{"label":"a","text":"4.50 m/s"},{"label":"b","text":"10.8 m/s"},{"label":"c","text":"19.6 m/s"},{"label":"d","text":"44.1 m/s"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch03.sec02.q008","sourceId":"fs-id1168439816328","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"A student calculated the final velocity of a train that decelerated from 30.5 m/s and got an answer of -43.34 m/s. Which of the following might indicate that he made a mistake in his calculation?","images":[],"choices":[{"label":"a","text":"The sign of the final velocity is wrong."},{"label":"b","text":"The magnitude of the answer is too small."},{"label":"c","text":"There are too few significant digits in the answer."},{"label":"d","text":"The units in the initial velocity are incorrect."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch03.sec02.q009","sourceId":"eip-id1166848824546","category":"concept","categoryLabel":"Concept Items (Câu hỏi khái niệm)","isMultipleChoice":true,"prompt":"Create your own kinematics problem. Then, create a flow chart showing the steps someone would need to take to solve the problem.","images":[],"choices":[{"label":"a","text":"Acceleration"},{"label":"b","text":"Distance"},{"label":"c","text":"Displacement"},{"label":"d","text":"Force"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch03.sec02.q011","sourceId":"fs-id1168440248103","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"A student is asked to solve a problem:\nAn object falls from a height for 2.0 s, at which point it is still 60 m above the ground. What will be the velocity of the object when it hits the ground?\nWhich of the following provides the correct order of kinematic equations that can be used to solve the problem?","images":[],"choices":[{"label":"a","text":"First use \\({v}^{2} = {v}_{0}{}^{2} + 2a(d - {d}_{0})\\text{,}\\) then use \\(v = {v}_{0} + at.\\)"},{"label":"b","text":"First use \\(v = {v}_{0} + at,\\) then use \\({v}^{2} = {v}_{0}{}^{2} + 2a(d - {d}_{0})\\text{.}\\)"},{"label":"c","text":"First use \\(d = {d}_{0} + {v}_{0}t + \\frac{1}{2}a{t}^{2},\\) then use \\(v = {v}_{0} + at.\\)"},{"label":"d","text":"First use \\(v = {v}_{0} + at,\\) then use \\(d - {d}_{0} = {v}_{0}t + \\frac{1}{2}a{t}^{2}.\\)"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch03.sec02.q012","sourceId":"eip-id1166847120244","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"Skydivers are affected by acceleration due to gravity and by air resistance. Eventually, they reach a speed where the force of gravity is almost equal to the force of air resistance. As they approach that point, their acceleration decreases in magnitude to near zero.\nPart A. Describe the shape of the graph of the magnitude of the acceleration versus time for a falling skydiver.\nPart B. Describe the shape of the graph of the magnitude of the velocity versus time for a falling skydiver.\nPart C. Describe the shape of the graph of the magnitude of the displacement versus time for a falling skydiver.","images":[],"choices":[{"label":"a","text":"Part A. Begins with a nonzero y-intercept with a downward slope that levels off at zero; Part B. Begins at zero with an upward slope that decreases in magnitude until the curve levels off; Part C. Begins at zero with an upward slope that increases in magnitude until it becomes a positive constant"},{"label":"b","text":"Part A. Begins with a nonzero y-intercept with an upward slope that levels off at zero; Part B. Begins at zero with an upward slope that decreases in magnitude until the curve levels off; Part C. Begins at zero with an upward slope that increases in magnitude until it becomes a positive constant"},{"label":"c","text":"Part A. Begins with a nonzero y-intercept with a downward slope that levels off at zero; Part B. Begins at zero with a downward slope that decreases in magnitude until the curve levels off; Part C. Begins at zero with an upward slope that increases in magnitude until it becomes a positive constant"},{"label":"d","text":"Part A. Begins with a nonzero y-intercept with an upward slope that levels off at zero; Part B. Begins at zero with a downward slope that decreases in magnitude until the curve levels off; Part C. Begins at zero with an upward slope that increases in magnitude until it becomes a positive constant"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch03.sec02.q013","sourceId":"eip-id1166849473582","category":"critical-thinking","categoryLabel":"Critical Thinking (Tư duy phản biện)","isMultipleChoice":true,"prompt":"Which graph in the previous problem has a positive slope?","images":[],"choices":[{"label":"a","text":"Displacement versus time only"},{"label":"b","text":"Acceleration versus time and velocity versus time"},{"label":"c","text":"Velocity versus time and displacement versus time"},{"label":"d","text":"Acceleration versus time and displacement versus time"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch03.sec02.q014","sourceId":"fs-id1167066955525","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"Dragsters can reach a top speed of 145 m/s in only 4.45 s. Calculate the average acceleration for such a dragster.","images":[],"choices":[{"label":"a","text":"-32.6 m/s 2"},{"label":"b","text":"0 m/s 2"},{"label":"c","text":"32.6 m/s 2"},{"label":"d","text":"145 m/s 2"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch03.sec02.q015","sourceId":"fs-id1167067087927","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"An Olympic-class sprinter starts a race with an acceleration of 4.50 m/s 2 . Assuming she can maintain that acceleration, what is her speed 2.40 s later?","images":[],"choices":[{"label":"a","text":"4.50 m/s"},{"label":"b","text":"10.8 m/s"},{"label":"c","text":"19.6 m/s"},{"label":"d","text":"44.1 m/s"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch03.sec02.q018","sourceId":"fs-id1168439787100","category":"problems","categoryLabel":"Problems (Bài toán tính toán)","isMultipleChoice":true,"prompt":"A swan on a lake gets airborne by flapping its wings and running on top of the water. If the swan must reach a velocity of 6.00 m/s to take off and it accelerates from rest at a constant rate of 0.350 m/s 2 , how far will it travel before becoming airborne?","images":[],"choices":[{"label":"a","text":"-8.60 m"},{"label":"b","text":"8.60 m"},{"label":"c","text":"-51.4 m"},{"label":"d","text":"51.4 m"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch03.sec02.q020","sourceId":"fs-idm26263872","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"For the motion of a falling object, which graphs are straight lines?","images":[],"choices":[{"label":"a","text":"Acceleration versus time only"},{"label":"b","text":"Displacement versus time only"},{"label":"c","text":"Displacement versus time and acceleration versus time"},{"label":"d","text":"Velocity versus time and acceleration versus time"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch03.sec02.q021","sourceId":"fs-idm29166176","category":"test-prep-mc","categoryLabel":"Test Prep — Trắc nghiệm","isMultipleChoice":true,"prompt":"A bullet in a gun is accelerated from the firing chamber to the end of the barrel at an average rate of 6.30×10 5 m/s 2 for 8.10×10 -4 s. What is the bullet’s final velocity when it leaves the barrel, commonly known as the muzzle velocity?","images":[],"choices":[{"label":"a","text":"7.79 m/s"},{"label":"b","text":"51.0 m/s"},{"label":"c","text":"510 m/s"},{"label":"d","text":"1020 m/s"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch03.sec02.q022","sourceId":"fs-id1168439952886","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"If a plot of displacement versus time is linear, what can be said about the acceleration?","images":[],"choices":[{"label":"a","text":"Acceleration is 0."},{"label":"b","text":"Acceleration is a non-zero constant."},{"label":"c","text":"Acceleration is positive."},{"label":"d","text":"Acceleration is negative."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch03.sec02.q023","sourceId":"fs-idp35049024","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"True or False: The image shows a velocity vs. time graph for a jet car. If you take the slope at any point on the graph, the jet cars acceleration will be 5.0 m/s 2 .","images":[{"sourceId":"fs-id1164567473857","filename":"CNX_HSPhysics_03_02_jet_img.jpg","relativePath":"media/CNX_HSPhysics_03_02_jet_img.jpg","alt":"A graph titled velocity vs. time plots time (s) on the x axis and velocity (m/s) on the y-axis. At time zero, the velocity is about 15 meters per second. The line extends at a constant rate and reaches a velocity of 170 at a time of 30 seconds."}],"choices":[{"label":"a","text":"True"},{"label":"b","text":"False"}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch03.sec02.q024","sourceId":"fs-idm26422928","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"When plotted on the blank plots, which answer choice would show the motion of an object that has uniformly accelerated from 2 m/s to 8 m/s in 3 s?","images":[{"sourceId":"fs-id1164565931920","filename":"CNX_HSPhysics_03_02_blank_img.jpg","relativePath":"media/CNX_HSPhysics_03_02_blank_img.jpg","alt":"Two blank graphs are shown. The horizontal axis of graph a is labeled Time, s and is numbered from 0 to 4 in increments of 1. The vertical axis of graph a is labeled Velocity, m/s and is numbered from 0 to 8 in increments of 2. The horizontal axis of graph b is labeled Time, s and is numbered from 0 to 4 in increments of 1. The vertical axis of graph b is labeled Acceleration, m/s^2 and is numbered from 0 to 4 in increments of 1."}],"choices":[{"label":"a","text":"The plot on the left shows a line from (0,2) to (3,8) while the plot on the right shows a line from (0,2) to (3,2)."},{"label":"b","text":"The plot on the left shows a line from (0,2) to (3,8) while the plot on the right shows a line from (0,3) to (3,3)."},{"label":"c","text":"The plot on the left shows a line from (0,8) to (3,2) while the plot on the right shows a line from (0,2) to (3,2)."},{"label":"d","text":"The plot on the left shows a line from (0,8) to (3,2) while the plot on the right shows a line from (0,3) to (3,3)."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch03.sec02.q025","sourceId":"fs-idm14542320","category":"test-prep-sa","categoryLabel":"Test Prep — Trả lời ngắn","isMultipleChoice":true,"prompt":"When is a plot of velocity versus time a straight line and when is it a curved line?","images":[],"choices":[{"label":"a","text":"It is a straight line when acceleration is changing and is a curved line when acceleration is constant."},{"label":"b","text":"It is a straight line when acceleration is constant and is a curved line when acceleration is changing."},{"label":"c","text":"It is a straight line when velocity is constant and is a curved line when velocity is changing."},{"label":"d","text":"It is a straight line when velocity is changing and is a curved line when velocity is constant."}],"hasOfficialSolution":false,"solution":null},{"uid":"hsphys.ch03.sec02.q026","sourceId":"fs-idp36045440","category":"test-prep-er","categoryLabel":"Test Prep — Tự luận mở rộng","isMultipleChoice":true,"prompt":"True or False: Consider an object that starts from rest and moves with constant acceleration. The plot of displacement versus time for such motion is a curved line while the plot of displacement versus time squared is a straight line.","images":[],"choices":[{"label":"a","text":"True"},{"label":"b","text":"False"}],"hasOfficialSolution":false,"solution":null}],"stats":{"learningObjectiveCount":2,"keyEquationCount":5,"subsectionCount":4,"workedExampleCount":2,"snapLabCount":0,"glossaryCount":3,"assessmentCount":18}}],"summary":{"totalSections":3,"totalKeyEquations":6,"totalWorkedExamples":4,"totalSnapLabs":1,"totalGlossaryTerms":6,"totalAssessments":29,"referencedMediaCount":9},"qualityGate":{"passed":true,"checkedUids":44,"errors":[],"warnings":[]}};
